<?php use App\Core\Csrf;use App\Core\View;?>
<div class="page-header"><div><p class="eyebrow">플랫폼 운영</p><h1>체험 계정 관리</h1><p class="muted">체험 데이터는 이 화면에서 삭제하지 않습니다. 종료 후 30일 보관 정책에 따라 별도 승인 절차로 관리합니다.</p></div></div>
<?php if($success):?><div class="alert alert-success"><?=View::e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-error"><?=View::e($error)?></div><?php endif;?>
<section class="panel"><form method="get" action="/control/trials" class="form-grid"><label>검색<input name="q" value="<?=View::e($filters['query'])?>" maxlength="100" placeholder="교회명 또는 주소 ID"></label><label>상태<select name="status"><option value="">전체</option><?php foreach(['trialing'=>'체험 중','expired'=>'종료','suspended'=>'정지','cancelled'=>'취소'] as $v=>$l):?><option value="<?=$v?>" <?=$filters['status']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><button type="submit">조회</button></form></section>
<?php foreach($trials as $trial):?><section class="panel"><div class="section-head"><div><h2><?=View::e($trial['name'])?></h2><p><?=View::e($trial['slug'])?> · <?=View::e($trial['plan_name'])?> · <?=View::e($trial['subscription_status'])?></p></div><strong><?=(int)$trial['remaining_days']>=0?(int)$trial['remaining_days'].'일 남음':abs((int)$trial['remaining_days']).'일 경과'?></strong></div><div class="stats-grid"><article class="card"><span>체험 종료</span><strong><?=View::e($trial['trial_ends_at']??'-')?></strong></article><article class="card"><span>이번 달 트래픽</span><strong><?=number_format(((int)$trial['traffic_bytes'])/1048576,1)?> MB</strong></article><article class="card"><span>저장공간</span><strong><?=number_format(((int)$trial['storage_bytes'])/1048576,1)?> MB</strong></article><article class="card"><span>초대장</span><strong><?=(int)$trial['invitation_count']?>개</strong></article><article class="card"><span>최근 로그인</span><strong><?=View::e($trial['last_login_at']??'기록 없음')?></strong></article></div>
<form method="post" action="/control/trials/<?=(int)$trial['subscription_id']?>/extend" class="form-grid"><input type="hidden" name="_token" value="<?=View::e(Csrf::token())?>"><label>연장 일수<input type="number" name="days" min="1" max="30" value="7" required></label><label class="full">작업 사유<input name="reason" minlength="10" maxlength="500" required placeholder="승인 근거와 요청 내용을 10자 이상 기록"></label><button class="button primary" type="submit">기간 연장</button></form>
<?php if($trial['subscription_status']==='trialing'):?><form method="post" action="/control/trials/<?=(int)$trial['subscription_id']?>/expire" class="inline-form"><input type="hidden" name="_token" value="<?=View::e(Csrf::token())?>"><input name="reason" minlength="10" maxlength="500" required placeholder="종료 사유(10자 이상)"><button class="button danger" type="submit">데이터 삭제 없이 종료</button></form><?php else:?><form method="post" action="/control/trials/<?=(int)$trial['subscription_id']?>/recover" class="inline-form"><input type="hidden" name="_token" value="<?=View::e(Csrf::token())?>"><input name="reason" minlength="10" maxlength="500" required placeholder="복구 승인 사유(10자 이상)"><button class="button" type="submit">체험 복구</button></form><?php endif;?></section><?php endforeach;?>
<?php if($trials===[]):?><section class="panel empty">조건에 맞는 체험 계정이 없습니다.</section><?php endif;?>
